python3 -c "
import json

# Let's look at what ALL 482 hook events actually are
jsonl_path = '.claude/sessions/421d98e5-70a9-47a1-ad35-c390e297d5f4.jsonl'

hook_sources = {}
with open(jsonl_path) as f:
    for line in f:
        try:
            obj = json.loads(line)
            if obj.get('type') == 'progress':
                data = obj.get('data',{})
                if data.get('type') == 'hook_progress':
                    name = data.get('hookName', data.get('hookEvent','unknown'))
                    hook_sources[name] = hook_sources.get(name, 0) + 1
        except: pass

print('Hook event breakdown (482 total):')
for k,v in sorted(hook_sources.items(), key=lambda x:-x[1]):
    print(f'  {k}: {v}')
"
